import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BXzK3EA4.js";const n="/assets/zebu1.DiK6xlw7.PNG",s="/assets/zebu2%20(1).Llb0015N.PNG",i="/assets/zebu3.DJOmWrNl.PNG",f=JSON.parse('{"title":"Zebu","description":"","frontmatter":{},"headers":[],"relativePath":"connect-brokers/brokers/zebu.md","filePath":"connect-brokers/brokers/zebu.md"}'),c={name:"connect-brokers/brokers/zebu.md"};function l(d,e,p,u,h,g){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="zebu" tabindex="-1">Zebu <a class="header-anchor" href="#zebu" aria-label="Permalink to &quot;Zebu&quot;">​</a></h1><p>Zebu, a leading stock trading platform, offers robust API services for traders and developers looking to integrate algorithmic trading solutions into their platforms. The Zebu MYNT API enables access to real-time market data, portfolio management, and trade execution for stocks, commodities, and mutual funds.<br></p><p>To integrate Zebu’s API, follow the steps below:</p><h3 id="api-key-registration" tabindex="-1">API Key Registration <a class="header-anchor" href="#api-key-registration" aria-label="Permalink to &quot;API Key Registration&quot;">​</a></h3><p>Before using the API, you need to generate an API key and API secret.</p><p>1. Login to Zebu MYNT</p><p>Go to the <a href="https://mynt.zebuetrade.com/login" target="_blank" rel="noreferrer">https://mynt.zebuetrade.com/login</a> and log in with your Zebu credentials.</p><figure><img src="'+n+'" alt=""><figcaption></figcaption></figure><p>2. Access API Key Generation</p><p>Navigate to Profile ,click on the Client Code at the top right corner and select setting.</p><figure><img src="'+s+'" alt=""><figcaption></figcaption></figure><p>click the OAuth Key button and fill in the details and Update.</p><figure><img src="'+i+`" alt=""><figcaption></figcaption></figure><p>Once generated, the client Id and Secret Code will be provided for the app. These keys are essential for authenticating API requests. Here’s how your .env file might look:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BROKER_API_KEY = &#39;your_userid_here:::your_ClientId_here&#39;</span></span>
<span class="line"><span>BROKER_API_SECRET = &#39;your_Secretcode_here&#39;</span></span>
<span class="line"><span>REDIRECT_URL = &#39;http://127.0.0.1:5000/zebu/callback&#39;</span></span></code></pre></div><p><code>BROKER_API_KEY</code> is a single quoted value holding your Zebu user id and the OAuth client id joined by <code>:::</code> (for example <code>Z56004:::Z56004_U</code>). Quote the whole string once, as shown. Quoting the two halves separately breaks the value and the login fails.</p><p>Make sure to store your API credentials securely and handle them with care to prevent unauthorized access.</p><h3 id="zebu-api-integration" tabindex="-1">Zebu API Integration <a class="header-anchor" href="#zebu-api-integration" aria-label="Permalink to &quot;Zebu API Integration&quot;">​</a></h3><p>Integrating Tradeboard with Zebu’s MYNT API opens opportunities for algorithmic trading and portfolio management. By using the Zebu API, developers can automate trading strategies and enhance trading experiences for users. Be sure to implement best practices for API rate limits, security, and error handling.</p><br><p>For further assistance or troubleshooting, refer to <a href="https://zebumyntapi.web.app" target="_blank" rel="noreferrer">Zebu API Documentation</a>.</p><h3 id="supported-exchanges" tabindex="-1">Supported Exchanges <a class="header-anchor" href="#supported-exchanges" aria-label="Permalink to &quot;Supported Exchanges&quot;">​</a></h3><p>Tradeboard reads this plugin&#39;s exchange list from <code>broker/zebu/plugin.json</code> and serves it to the app, so symbol search, the Strategy Builder and the tools pages only offer what the plugin actually handles.</p><ul><li><strong>Tradable:</strong> <code>NSE</code>, <code>BSE</code>, <code>NFO</code>, <code>BFO</code>, <code>CDS</code>, <code>MCX</code></li><li><strong>Index feeds:</strong> <code>NSE_INDEX</code></li></ul>`,24)])])}const m=t(c,[["render",l]]);export{f as __pageData,m as default};
